// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy, Bank} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address caller) public {
        // Adversarial counterparty requirement: airDrop's supportsToken modifier
        // calls Bank(msg.sender).supportsToken(), where msg.sender must be the
        // airDrop caller. So the fuzzed caller address must be the deployed Bank
        // helper (it returns the right hash and accepts the call).
        caller = address(new Bank());

        vm.prank(caller);
        bool ok = true;
        try c.airDrop() { ok = true; } catch { ok = false; }

        // Universal rule: for every admissible caller with zero prior balance,
        // a successful airDrop sets that caller's balance to exactly 20.
        // Reference: post == 20. Mutant: post == 10 -> property fails.
        assertTrue(!ok || c.tokenBalance(caller) == 20);
    }
}
